   242	/*
   243	  There are some (master) protocols that are informative, meaning that it shows
   244	  what is the subprotocol about, but also that the subprotocol isn't a real protocol.
   245	
   246	  Example:
   247	  - DNS is informative as if we see a DNS request for www.facebook.com, the
   248	  returned protocol is DNS.Facebook, but Facebook isn't a real subprotocol but
   249	  rather it indicates a query for Facebook and not Facebook traffic.
   250	  - HTTP/SSL are NOT informative as SSL.Facebook (likely) means that this is
   251	  SSL (HTTPS) traffic containg Facebook traffic.
   252	*/
   253	u_int8_t ndpi_is_subprotocol_informative(struct ndpi_detection_module_struct *ndpi_str,
   254	                                         u_int16_t protoId) {
   255	  if(protoId >= NDPI_MAX_SUPPORTED_PROTOCOLS+NDPI_MAX_NUM_CUSTOM_PROTOCOLS)
   256	    return(0);
   257	
   258	  switch(protoId) {
   259	    /* All dissectors that have calls to ndpi_match_host_subprotocol() */
   260	  case NDPI_PROTOCOL_DNS:
   261	  case NDPI_PROTOCOL_HTTP:
   262	  case NDPI_PROTOCOL_TLS:
   263	  case NDPI_PROTOCOL_QUIC:
   264	  case NDPI_PROTOCOL_FBZERO:
   265	    return(1);
   266	    break;
   267	
   268	  default:
   269	    return(0);
   270	  }
